#include "uitk/widgets/header_bar.h"

#include <algorithm>
#include <cmath>

#include "uitk/widgets/glyphs.h"
#include "uitk/widgets/widget_host.h"

#include "adwaita_window_icons.h"   // generated by CMake from assets/icons/adwaita

namespace uitk {

namespace {
enum { ICON_MIN, ICON_MAX, ICON_RESTORE, ICON_CLOSE };

// Window-control icon for the theme's chrome style.
const Image& control_icon(WindowControlsStyle style, int which) {
    if (style == WindowControlsStyle::Flat) {
        static const Glyph g[4] = {Glyph::Minimize, Glyph::Maximize, Glyph::Restore, Glyph::Close};
        return glyph(g[which]);
    }
    static Image adwaita[4] = {
        Image::from_svg(ADW_WINDOW_MINIMIZE), Image::from_svg(ADW_WINDOW_MAXIMIZE),
        Image::from_svg(ADW_WINDOW_RESTORE),  Image::from_svg(ADW_WINDOW_CLOSE),
    };
    return adwaita[which];
}
} // namespace

HeaderBar::HeaderBar(std::string title) {
    start_ = &add<Box>(Orientation::Horizontal, 2.f);
    end_ = &add<Box>(Orientation::Horizontal, 2.f);
    title_ = &add<Label>(std::move(title), TextRole::Chrome);
    title_->set_text_align(TextAlign::Center);
    title_->set_ellipsize(true);
    title_->set_backdrop_dim(true);

    controls_ = &add<Box>(Orientation::Horizontal, 0.f);
    auto make = [&]() -> Button& {
        Button& b = controls_->add<Button>(Image(), ButtonStyle::WindowControl);
        b.set_focusable(false);      // window controls are not in the Tab chain
        b.set_backdrop_dim(true);
        return b;
    };
    min_ = &make();
    max_ = &make();
    close_ = &make();

    min_->clicked.connect([this] { if (auto* h = host(); h && h->window()) h->window()->minimize(); });
    max_->clicked.connect([this] {
        if (auto* h = host(); h && h->window()) h->window()->set_maximized(!h->window()->maximized());
    });
    close_->clicked.connect([this] { close_requested.emit(); });
}

void HeaderBar::set_show_window_controls(bool show) { controls_->set_visible(show); }

void HeaderBar::set_maximized(bool m) {
    if (m == maximized_) return;
    maximized_ = m;
    control_style_ = -1;   // re-pick the maximize/restore icon
    invalidate_layout();
}

void HeaderBar::apply_control_style(const Theme& t) {
    if (control_style_ == (int)t.window_controls) return;
    control_style_ = (int)t.window_controls;
    min_->set_icon(control_icon(t.window_controls, ICON_MIN));
    max_->set_icon(control_icon(t.window_controls, maximized_ ? ICON_RESTORE : ICON_MAX));
    close_->set_icon(control_icon(t.window_controls, ICON_CLOSE));
    // Circular controls sit apart; flat ones form one continuous strip.
    controls_->set_spacing(t.window_controls == WindowControlsStyle::Circular ? t.spacing : 0.f);
}

Size HeaderBar::measure(float, const Theme& t) {
    apply_control_style(t);   // icons decide the controls' size
    float w = 0;
    for (Box* b : {start_, end_, controls_})
        if (b->visible()) w += b->measure_clamped(1e9f, t).width;
    return {w + title_->measure_clamped(1e9f, t).width + 24, t.header_height};
}

void HeaderBar::layout(const Theme& t) {
    apply_control_style(t);
    float h = size().height, w = size().width;
    const bool flat = t.window_controls == WindowControlsStyle::Flat;
    const float edge = flat ? 0.f : 6.f;   // flat controls run to the window edge

    auto place_box = [&](Box* b, float x, bool from_right) -> float {
        if (!b->visible() || b->children().empty()) return 0;
        Size s = b->measure_clamped(1e9f, t);
        float bx = from_right ? x - s.width : x;
        b->set_bounds({std::round(bx), 0, std::round(s.width), h});   // children centred vertically
        b->layout(t);
        return s.width;
    };

    float left = 6 + place_box(start_, 6, false);
    float right = w - edge;
    right -= place_box(controls_, right, true);
    if (!end_->children().empty()) right -= place_box(end_, right - t.spacing, true) + t.spacing;

    float avail = std::max(0.f, right - left - 2 * t.spacing);
    float natural = title_->measure_clamped(1e9f, t).width;
    if (t.title_style == TitleStyle::CommandCenter) {
        // Input-like box centred on the window, shrinking if the buttons need the room.
        float bw = std::min(t.command_center_width, avail);
        float bh = t.command_center_height;
        float bx = std::clamp((w - bw) / 2, left + t.spacing, std::max(left + t.spacing, right - t.spacing - bw));
        title_box_ = {std::round(bx), std::round((h - bh) / 2), std::round(bw), bh};
        float pad = 10;
        title_->set_bounds({title_box_.x + pad, 0, std::max(0.f, title_box_.width - 2 * pad), h});
    } else {
        title_box_ = {};
        float tw = std::min(natural, avail);
        float tx = std::clamp((w - tw) / 2, left + t.spacing, std::max(left + t.spacing, right - t.spacing - tw));
        title_->set_bounds({std::round(tx), 0, std::round(tw), h});
    }
}

void HeaderBar::paint(PaintContext& ctx) {
    if (title_box_.empty()) return;
    const Theme& t = ctx.theme;
    ctx.canvas.draw_rrect(title_box_, t.radius + 2, Paint::fill(t.input_bg));
    ctx.canvas.draw_rrect(title_box_.inset(0.5f, 0.5f), t.radius + 1.5f, Paint::stroke(t.input_border, 1));
}

bool HeaderBar::on_pointer(const PointerEvent& e) {
    if (e.type != PointerEvent::Type::Down) return false;
    Window* win = host() ? host()->window() : nullptr;
    if (!win) return true;
    if (e.button == PointerButton::Right) {
        win->show_window_menu(to_window(e.pos));
    } else if (e.button == PointerButton::Left) {
        if (e.click_count == 2) win->set_maximized(!win->maximized());
        else win->begin_move();
    }
    host()->release_capture();   // the compositor owns the pointer now; no Up will arrive
    return true;
}

} // namespace uitk
